// Não confiar no usuário salvo na sessão para identidade visual: pode conter nome de demonstração antigo.
let currentIdentity={};
let directoryProfile={available:false,attributes:{}};
function identityDisplayName(){const a=directoryProfile.attributes||{};return a.displayName||[a.givenName,a.sn].filter(Boolean).join(' ')||currentIdentity.name||currentIdentity.login||currentIdentity.subject||'Usuário'}
function initialsFor(name){return String(name||'U').trim().split(/\\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'U'}
function applyCurrentIdentity(){const name=identityDisplayName(),roles=currentIdentity.roles||[],roleText=roles.length?roles.join(' · '):(currentIdentity.permissions?.includes('permission.manage')?'Administrador':'Usuário');document.querySelectorAll('.profile-main b').forEach(x=>x.textContent=name);document.querySelectorAll('.profile-main small').forEach(x=>x.textContent=roleText);document.querySelectorAll('[data-profile]').forEach(x=>x.setAttribute('aria-label',`Abrir perfil de ${name}`));{const add=document.querySelector('.tiny-add');if(add)add.hidden=!can('catalog.manage')}document.querySelectorAll('.top-profile').forEach(x=>x.title=`Abrir perfil de ${name}`);applyProfilePhoto()}
function applyProfilePhoto(){const photo=localStorage.getItem('atlas-ti-profile-photo'),initials=initialsFor(identityDisplayName());document.querySelectorAll('[data-avatar]').forEach(el=>{if(photo){el.innerHTML=`<img src="${photo}" alt="Foto do perfil">`;el.classList.add('has-photo')}else{el.textContent=initials;el.classList.remove('has-photo')}})}
