function usersAdmin(tab='users'){showModal(`<div class="modal-head"><div><h3>Usuários e grupos</h3><p>Perfis, grupos de permissão e histórico de alterações.</p></div><div class="modal-head-actions"><a class="au-fullscreen" href="./admin-users.html" title="Abrir em página inteira">Página inteira ↗</a><button class="close-btn" data-close>×</button></div></div><div class="modal-body users-modal-body"><div id="usersMount"></div></div>`);$('#modal').classList.add('users-modal');const mountUsers=()=>{if(!window.AtlasUsers){$('#usersMount').innerHTML='<div class="empty-state">Não foi possível carregar o módulo de usuários. Atualize a página (Ctrl+F5).</div>';return}window.AtlasUsers.mount($('#usersMount'),{mode:'popup',tab,identity:currentIdentity,onBack:adminMenu,backLabel:'Administração',toast})};Promise.resolve(typeof identityReady!=='undefined'?identityReady:null).then(mountUsers,mountUsers)}
